#pragma once
namespace hp {
inline constexpr char photoWebPage[]=R"PHOTOS(<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Home-Display · Fotos</title>
<style>*{box-sizing:border-box}body{margin:0;background:#101923;color:#edf3f9;font:16px system-ui}main{max-width:1200px;margin:auto;padding:24px}a{color:#92d2ff}section{background:#1c2a38;border:1px solid #334858;border-radius:18px;padding:24px;margin:18px 0}h1,h2{margin-top:0}label{display:block;margin:14px 0}input,select,textarea,button{font:inherit;color:inherit;background:#263c4c;border:1px solid #607c90;border-radius:10px;padding:11px;min-height:44px}input:not([type=checkbox]),select,textarea{width:100%}input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle;margin-right:10px}button{cursor:pointer}button:disabled{opacity:.5}.primary{background:#217bb2}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.actions{display:flex;gap:10px;flex-wrap:wrap}.days{display:flex;gap:12px;flex-wrap:wrap}.days label{white-space:nowrap}.hint{color:#b8c8d5;line-height:1.5}#status{position:sticky;top:0;background:#101923;padding:14px;z-index:1;white-space:pre-wrap}progress{width:100%;height:22px}textarea{min-height:100px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #92d2ff}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:14px}section{padding:18px}}</style>
<main><a href="/">← Home-Display</a> · <a href="/files">Dateien</a><h1>Fotos & Bilderrahmen</h1><p class="hint">Gemeinsame Fotos von SD, USB und eingerichteten NAS-Quellen. Änderungen benötigen die Freigabe der Einstellungen am Display.</p><p id="status" role="status" aria-live="polite">Einstellungen werden geladen …</p>
<section><h2>Bilder hinzufügen</h2><div class="grid"><label>Speicherziel<select id="target"><option value="sd">SD-Karte</option><option value="usb">USB-Stick</option></select></label><label>Album unter Bilder (optional, auch Urlaub/2026)<input id="album" maxlength="120" placeholder="Urlaub/2026"></label></div><div id="imageDrop" tabindex="0" role="button" style="padding:24px;border:1px dashed #607c90;border-radius:12px">Bilder hier ablegen oder auswählen (bis zu 128)</div><label>Bilder auswählen<input id="images" type="file" multiple accept=".jpg,.jpeg,.png,.bmp,.gif,.webp,.tga,.qoi"></label><div class="actions"><button class="primary" id="upload">Bilder hochladen</button><button id="stopUpload" disabled>Upload abbrechen</button></div><p id="fileUploadStatus" class="hint" aria-live="polite"></p><progress id="fileProgress" max="100" value="0"></progress><progress id="progress" max="100" value="0"></progress><ol id="uploadResults" class="hint"></ol><p class="hint">Je Bild höchstens 4 MiB; PNG/WebP/GIF usw. bis 4 Megapixel, JPEG abhängig vom Decoder bis 64 Megapixel. Keine vorhandene Datei wird überschrieben. NAS bleibt als Lesequelle verfügbar; der Upload schreibt auf SD oder USB. Neue Alben werden als Ordner angelegt. Ohne automatische Standardquellen den Zielordner unten zusätzlich auswählen.</p></section>
<form id="scheduleForm"><section><h2>Zeitplan & Rückkehr</h2><label><input id="schedule" type="checkbox">Automatischen Bilderrahmen aktivieren</label><div class="grid"><label>Startzeit<input id="start" type="time" value="07:00" required></label><label>Endzeit<input id="end" type="time" value="19:00" required></label></div><div id="days" class="days"></div><label><input id="takeover" type="checkbox">Zum Zeitbeginn auch eine andere offene App verlassen und bei Inaktivität zum Bilderrahmen zurückkehren</label><div class="grid"><label>Rückkehr nach Sekunden<input id="returnAfter" type="number" min="5" max="3600" required></label><label>Bildwechsel nach Sekunden<input id="interval" type="number" min="5" max="3600" required></label></div><p class="hint">Während des Zeitfensters ersetzt der Bilderrahmen Dimmung/Bildschirm-Aus. Andere Apps bleiben vorübergehend nutzbar. Die Rückkehr erfolgt spätestens vor der normalen Dimmung. Gleiche Start-/Endzeit bedeutet ganztägig; über Mitternacht zählt der Starttag. Gerätesperre und Sprechanlagenrufe haben Vorrang. Ohne gültige Uhrzeit startet keine Automatik.</p><div class="actions"><button type="button" id="startNow">Jetzt starten</button><button type="button" id="pause">Dieses Zeitfenster pausieren</button><button type="button" id="resume">Automatik fortsetzen</button></div><p class="hint">Dauerhaft ausschalten: Automatik deaktivieren und speichern. Eine Pause endet beim nächsten Zeitfenster oder Neustart.</p><button class="primary" type="submit">Zeitplan speichern</button></section></form>
<form id="libraryForm"><section><h2>Bibliothek & Sortierung</h2><label><input id="automaticFolders" type="checkbox" checked>Bilder auf SD und USB automatisch einlesen, einschließlich Unterordnern</label><label><input id="recursive" type="checkbox">Unterordner zusätzlicher Quellen einlesen (bis zu 4 Ebenen)</label><div class="grid"><label>Sortieren nach<select id="sortDate"><option value="date">Datum</option><option value="name">Name</option></select></label><label>Reihenfolge<select id="descending"><option value="true">Absteigend / neueste zuerst</option><option value="false">Aufsteigend / älteste zuerst</option></select></label></div><p class="hint">Datum ist das Änderungsdatum der Datei, nicht EXIF-Aufnahmedatum. Unbekannte Daten stehen zuletzt. Der Bilderrahmen verwendet unabhängig davon den Zufallsdurchlauf ohne direkte Wiederholung.</p><label>Maximale Renderauflösung (längste Kante)<select id="renderEdge"><option value="800">Sparsam · 800 px</option><option value="1280" selected>Standard · 1280 px</option><option value="1600">Qualität · 1600 px</option><option value="1920">Hoch · 1920 px</option></select></label><p class="hint">Seitenverhältnis bleibt erhalten, auch bei Hochkantbildern. Höchstens 2 Megapixel pro Renderbild. Zoom nutzt vorhandene Pixel statt ständig neu zu decodieren.</p><label>Zusätzliche Quellordner – ein URI je Zeile, höchstens 8<textarea id="folders" placeholder="nas1:/Fotos&#10;sd:/AndereFotos"></textarea></label><div class="actions"><button class="primary" type="submit">Bibliothek speichern</button><button type="button" id="reload">Neu laden</button></div></section></form>
<section><h2>Favoriten</h2><label>Bild-URIs – eine Datei je Zeile, höchstens 32<textarea id="favorites" placeholder="usb:/Bilder/Urlaub/strand.jpg"></textarea></label><button id="saveFavorites">Favoriten speichern</button></section><details><summary>Bildlade-Diagnose</summary><pre id="imageMetrics"></pre></details></main>
<script src="/app-web-lifecycle.js"></script><script>'use strict';
const $=id=>document.getElementById(id);let token='',revision=0,busy=false,uploadController=null,model=null,photoFiles=[],storageFree={};
const messages={settings_locked:'Einstellungen mit dem System-PIN am Display freigeben.',settings_locked_or_invalid:'PIN-Freigabe und Eingaben prüfen.',revision_conflict:'Zwischenzeitlich geändert: Neu laden und Änderung erneut eingeben.',photos_settings_invalid:'Ordner, Bild-URIs, Zeiten und Grenzen prüfen.',photos_settings_range:'Zeiten und Zahlen außerhalb der erlaubten Grenzen.',photos_write_failed:'Speichern fehlgeschlagen. Speicher und PIN prüfen.'};
function status(s){$('status').textContent=s}function lines(id,max){const rows=$(id).value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(rows.length>max)throw Error('Höchstens '+max+' Einträge.');return rows}
async function csrf(){if(!token){const r=await hpWeb.fetch('/api/csrf');if(!r.ok)throw Error('Anmeldung erforderlich');token=(await r.json()).token}return token}
async function job(op,args={}){await csrf();let r=await hpWeb.fetch('/api/photos/job',{method:'POST',headers:{'Content-Type':'application/json','X-HP-CSRF':token},body:JSON.stringify({op,args})});if(!r.ok)throw Error(await r.text());const {job:id}=await r.json();for(let i=0;i<50;i++){await new Promise(resolve=>setTimeout(resolve,200));r=await hpWeb.fetch('/api/photos/result?id='+id);if(!r.ok)throw Error(await r.text());const v=await r.json();if(v.done){if(!v.ok)throw Error(messages[v.error]||v.error);return v.value}}throw Error('Zeitlimit. Neu laden; Änderungen können bereits gespeichert sein.')}
function time(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}function minutes(id){const parts=$(id).value.split(':').map(Number);if(parts.length!==2||!Number.isFinite(parts[0])||!Number.isFinite(parts[1])||parts[0]>23||parts[1]>59)throw Error('Uhrzeit prüfen');return parts[0]*60+parts[1]}
function show(v){storageFree=v.storageFree||{};$('imageMetrics').textContent=JSON.stringify(v.imageMetrics||{},null,2);model=v.settings;revision=v.revision;for(const key of ['schedule','takeover','automaticFolders','recursive'])$(key).checked=!!model[key];$('start').value=time(model.start);$('end').value=time(model.end);$('interval').value=model.interval;$('returnAfter').value=model.returnAfter;$('renderEdge').value=String(model.renderEdge||1280);$('sortDate').value=model.sortDate?'date':'name';$('descending').value=String(model.descending);$('folders').value=model.folders.join('\n');$('favorites').value=model.favorites.join('\n');document.querySelectorAll('#days input').forEach((x,i)=>x.checked=!!(model.days&(1<<i)));for(const option of $('target').options)option.disabled=!v.storage[option.value];if(!v.storage[$('target').value])$('target').value=v.storage.sd?'sd':v.storage.usb?'usb':''}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){if(e.name!=='AbortError')status(messages[e.message]||e.message)}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);$('stopUpload').disabled=!uploadController}}
async function load(){show(await job('get'));status('Aktueller Stand geladen.')}async function save(patch){const v=await job('save',{revision,patch});model=v.settings;revision=v.revision;status('Gespeichert. Das Display übernimmt die Einstellungen automatisch.')}
for(const [i,day] of ['So','Mo','Di','Mi','Do','Fr','Sa'].entries()){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';label.append(input,document.createTextNode(day));$('days').append(label)}
$('scheduleForm').onsubmit=e=>{e.preventDefault();run(()=>save({start:minutes('start'),end:minutes('end'),interval:Number($('interval').value),returnAfter:Number($('returnAfter').value),days:[...document.querySelectorAll('#days input')].reduce((v,x,i)=>v|(x.checked?1<<i:0),0),schedule:$('schedule').checked,takeover:$('takeover').checked}))};
$('libraryForm').onsubmit=e=>{e.preventDefault();run(()=>save({automaticFolders:$('automaticFolders').checked,recursive:$('recursive').checked,sortDate:$('sortDate').value==='date',descending:$('descending').value==='true',folders:lines('folders',8),renderEdge:Number($('renderEdge').value)}))};$('saveFavorites').onclick=()=>run(()=>save({favorites:lines('favorites',32)}));$('reload').onclick=()=>run(load);
for(const [id,op] of [['pause','pause'],['resume','resume'],['startNow','start']])$(id).onclick=()=>run(async()=>{await job(op);status('An das Display übergeben: '+$(''+id).textContent)});
async function uploadRequest(path,body,op='upload',onProgress){await csrf();return hpWeb.upload(op==='upload'?'/photos/upload':'/files/mkdir',body,{signal:uploadController.signal,headers:{'X-HP-CSRF':token,'X-Storage-Area':$('target').value,'X-Path':encodeURIComponent(path)},onProgress}).catch(e=>{if(op==='mkdir'&&e.status===409)return;throw e})}
function choosePhotos(files){if(uploadController)return;const selected=[...files];if(!selected.length||selected.length>128){status('1 bis 128 Bilder auswählen.');return}photoFiles=selected;$('fileUploadStatus').textContent=selected.length+' Datei(en) ausgewählt';$('uploadResults').replaceChildren()}
$('images').onchange=()=>choosePhotos($('images').files);
const drop=$('imageDrop');drop.onclick=()=>{if(!uploadController)$('images').click()};drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();drop.onclick()}};
drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#92d2ff'};drop.ondragleave=()=>drop.style.borderColor='';drop.ondrop=e=>{e.preventDefault();drop.style.borderColor='';choosePhotos(e.dataTransfer.files)};
$('upload').onclick=()=>run(async()=>{
 if(!$('target').value)throw Error('SD oder USB anschließen.');const files=photoFiles.slice();if(!files.length)throw Error('Bilder auswählen.');
 const area=$('target').value,album=$('album').value.trim();if(album.split('/').some(p=>p==='.'||p==='..')||/[\\:\x00-\x1f]/.test(album)||album.startsWith('/')||album.endsWith('/')||album.includes('//'))throw Error('Album-Pfad prüfen.');
 uploadController=new AbortController();$('stopUpload').disabled=false;for(const id of ['target','album','images'])$(id).disabled=true;$('uploadResults').replaceChildren();
 let doneBytes=0;const totalBytes=files.reduce((n,f)=>n+f.size,0);
 try{
  let path='/Bilder';await uploadRequest(path,new Uint8Array(),'mkdir');for(const part of album?album.split('/'):[]){path+='/'+part;await uploadRequest(path,new Uint8Array(),'mkdir')}
  const batch=await hpWeb.batch(files,async(file,index,total)=>{
   if(!/\.(jpe?g|png|bmp|gif|webp|tga|qoi)$/i.test(file.name)||!file.size||file.size>4194304)throw Error('Bildformat oder 4-MiB-Grenze prüfen.');
   if(Number.isFinite(storageFree[area])&&file.size+65536>storageFree[area])throw Error('Nicht genug freier Speicher.');
   $('fileProgress').value=0;$('fileUploadStatus').textContent=(index+1)+' / '+total+' · '+file.name;
   await uploadRequest(path+'/'+file.name,file,'upload',fraction=>{$('fileProgress').value=fraction*100;$('progress').value=totalBytes?(doneBytes+file.size*fraction)*100/totalBytes:0});
   if(Number.isFinite(storageFree[area]))storageFree[area]-=file.size;return 'Gespeichert';
  },{signal:uploadController.signal,max:128,onResult:(result,total)=>{
   const file=files[result.index],row=document.createElement('li');row.textContent=file.name+' — '+(result.ok?'Gespeichert':'Fehler: '+result.error.message);$('uploadResults').append(row);
   doneBytes+=file.size;$('progress').value=totalBytes?doneBytes*100/totalBytes:0;status((result.index+1)+' / '+total+' verarbeitet');
  }});
  photoFiles=files.slice(batch.results.length);
  status((batch.stopped?'Upload gestoppt. ':'Upload abgeschlossen. ')+batch.results.filter(r=>r.ok).length+' gespeichert; '+batch.results.filter(r=>!r.ok).length+' fehlgeschlagen; '+photoFiles.length+' nicht gestartet. Gespeicherte Bilder bleiben erhalten. Die Displaybibliothek aktualisiert sich automatisch.');
 }finally{uploadController=null;$('stopUpload').disabled=true;for(const id of ['target','album','images'])$(id).disabled=false;$('images').value=''}
});$('stopUpload').onclick=()=>{uploadController?.abort();$('stopUpload').disabled=true};
hpWeb.whenVisible(()=>run(load));
</script></html>)PHOTOS";
}
